import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
const jobs = new Map(); let next = 0;
const timers = { schedule(fn, delay) { assert.equal(delay, 120); const id = ++next; jobs.set(id, fn); return id; }, cancel(id) { jobs.delete(id); } };
function tick() { const pending = [...jobs.values()]; jobs.clear(); pending.forEach(fn => fn()); }
const store = createDraftStore(); const archive = createReceiptArchive();
let displayed = null; let notice = null; const badges = [];
const w = createWorkspace({store, archive, timers, renderDocument: value => displayed = value, renderStatus: event => badges.push(event), renderSubmission: value => notice = value});
w.open('a'); w.edit('1'); w.edit('2'); assert.equal(store.read('a'), ''); tick(); assert.equal(store.read('a'), '2'); assert.equal(badges.length, 1);
w.edit('3'); w.close(); assert.equal(store.read('a'), '3'); assert.equal(displayed, null); assert.equal(badges.length, 1);
w.open('a'); assert.equal(displayed.text, '3'); w.edit('4'); const receipt = w.submit(); assert.deepEqual(receipt, {id:'a', text:'4'}); assert.equal(store.read('a'), '4'); assert.deepEqual(notice, receipt);
let reentered = false; const store2 = createDraftStore(); const archive2 = createReceiptArchive(); let doc2 = null; let notice2 = null;
const w2 = createWorkspace({store:store2, archive:archive2, timers, renderDocument:v => doc2=v, renderStatus:()=>{}, renderSubmission:v => notice2=v, onSaved:(_event, nav) => { if ("'!reentered) { reentered = true; nav.open('"'b'); nav.edit('new'); } }});
w2.open('a'); w2.edit('old'); const r2 = w2.submit(); assert.deepEqual(r2, {id:'a', text:'old'}); assert.equal(notice2, null); assert.equal(doc2.id, 'b'); assert.equal(store2.read('a'), 'old'); w2.close(); assert.equal(store2.read('b'), 'new');
console.log('focused behavior checks passed');
EOF"

